describe('Error Clearing on Input Correction', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should clear error message when invalid input is corrected', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/submit-form').as('formSubmit');

    // Fill form with invalid email
    cy.get('[data-testid="email-input"]').type('invalid-email');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for API call
    cy.wait('@formSubmit');

    // Verify error message is displayed
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="email-error"]').should('contain', 'Please enter a valid email address');

    // Correct the invalid input
    cy.get('[data-testid="email-input"]').clear().type('valid.user@example.com');

    // Verify error message is cleared
    cy.get('[data-testid="email-error"]').should('not.exist');

    // Verify input field is no longer marked as invalid
    cy.get('[data-testid="email-input"]').should('have.class', 'valid-input');

    // Submit form again to verify successful submission
    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should clear error when multiple fields have errors and one is corrected', () => {
    // Intercept form submission API
    cy.intercept('POST', '/api/submit-form').as('formSubmit');

    // Fill form with invalid email and password
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="password-input"]').type('short');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for API call
    cy.wait('@formSubmit');

    // Verify both errors are displayed
    cy.get('[data-testid="email-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('be.visible');

    // Correct the email input
    cy.get('[data-testid="email-input"]').clear().type('valid.user@example.com');

    // Verify email error is cleared
    cy.get('[data-testid="email-error"]').should('not.exist');

    // Verify password error still exists
    cy.get('[data-testid="password-error"]').should('be.visible');
    cy.get('[data-testid="password-error"]').should('contain', 'Password must be at least 8 characters');

    // Verify email input is now valid
    cy.get('[data-testid="email-input"]').should('have.class', 'valid-input');

    // Correct the password input
    cy.get('[data-testid="password-input"]').clear().type('ValidPassword123');

    // Verify password error is cleared
    cy.get('[data-testid="password-error"]').should('not.exist');

    // Verify both fields are now valid
    cy.get('[data-testid="email-input"]').should('have.class', 'valid-input');
    cy.get('[data-testid="password-input"]').should('have.class', 'valid-input');

    // Submit form again
    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
